export default function next({ body, previousState }) {
  if (!Array.isArray(body.events)) throw Error("Expected LINE event array");
  const events = body.events.filter((e) => e?.type === "message" && e?.message?.type === "image");
  const i = previousState?.index ?? 0;
  if (i >= events.length) return { state: { index: i }, more: false, messageId: "", name: "none" };
  const id = String(events[i]?.message?.id ?? "");
  if (!/^[A-Za-z0-9_-]+$/.test(id)) throw Error("Invalid LINE message ID");
  return { state: { index: i + 1 }, more: true, messageId: id, name: id + ".jpg" };
}

