import { Buffer } from "node:buffer";
export default async function image({ messageId, token }, context) {
  if (!token) throw Error("Configure LINE access token");
  const r = await context.fetch(
    "https://api-data.line.me/v2/bot/message/" + encodeURIComponent(messageId) + "/content",
    { headers: { authorization: "Bearer " + token } },
  );
  if (!r.ok) throw Error("LINE content request failed");
  const b = Buffer.from(await r.arrayBuffer());
  if (!b.length) throw Error("Empty image");
  const mimeType = (r.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
  if (!["image/jpeg", "image/png"].includes(mimeType)) throw Error("Expected JPEG or PNG");
  return {
    contentBase64: b.toString("base64"),
    mimeType,
    name: messageId + (mimeType === "image/png" ? ".png" : ".jpg"),
  };
}

